from collections import OrderedDict, deque
from bisect import bisect_left
import heapq

def matrix_power(k, mod, a):
    n = len(a)

    def multiply(x, y):
        product = [[0] * n for _ in range(n)]
        for i in range(n):
            for middle in range(n):
                factor = x[i][middle]
                for j in range(n):
                    product[i][j] = (product[i][j] + factor * y[middle][j]) % mod
        return product
    result = [[int(i == j) for j in range(n)] for i in range(n)]
    base = [row[:] for row in a]
    while k:
        if k & 1:
            result = multiply(result, base)
        k //= 2
        if k:
            base = multiply(base, base)
    return [' '.join(map(str, row)) for row in result]

print(*matrix_power(3, 1000000007, [[1, 1], [1, 0]]), sep='\n')
print(*matrix_power(0, 7, [[0, 0], [0, 0]]), sep='\n')
